-- {"operators": "CTE,LEFT_JOIN,AGGREGATE", "complexity": "high", "is_incremental": true, "has_nulls": true, "has_cast": false, "has_case": false, "tables": "DISTRICT,CUSTOMER,OORDER", "openivm_verified": true}
WITH cust AS (SELECT C_W_ID, C_D_ID, COUNT(*) AS customers FROM CUSTOMER GROUP BY C_W_ID, C_D_ID), ord AS (SELECT O_W_ID, O_D_ID, COUNT(*) AS orders FROM OORDER GROUP BY O_W_ID, O_D_ID) SELECT d.D_W_ID, d.D_ID, COALESCE(c.customers, 0) AS customers, COALESCE(o.orders, 0) AS orders FROM DISTRICT d LEFT JOIN cust c ON d.D_W_ID = c.C_W_ID AND d.D_ID = c.C_D_ID LEFT JOIN ord o ON d.D_W_ID = o.O_W_ID AND d.D_ID = o.O_D_ID;
